package ru.ileech.ndicamera;

import android.content.Context;
import android.graphics.*;
import android.graphics.drawable.GradientDrawable;
import android.view.*;
import android.widget.*;
import java.util.*;

/** Native controls over the camera. HUD is never an input surface of the encoder. */
final class CameraHud extends FrameLayout {
 interface Actions{void action(String id);void zoom(float value);void focus(float x,float y,boolean hold);void exposure(float ev);}
 private final Actions actions;private final CameraController camera;private final Map<String,Button> buttons=new LinkedHashMap<>();private final Paint paint=new Paint(3);
 private final TextView brand,status,timer,bitrate,zoomText,source;private final ImageView logo;private final SeekBar zoom;
 boolean grid=true,hidden,scopes,frontLight;float level=-90,pointX=.5f,pointY=.5f;private int[] rgb,vector;private float downX,downY,downEv,pinchZoom;private boolean holding,swiping,multi;private int pointer=-1;
 private final ScaleGestureDetector scale;private final Runnable hold;private boolean programmatic;
 CameraHud(Context c,CameraController camera,Actions actions){super(c);this.camera=camera;this.actions=actions;setWillNotDraw(false);setBackgroundColor(Color.TRANSPARENT);setFocusable(true);
  logo=new ImageView(c);logo.setImageResource(R.drawable.ic_launcher);logo.setContentDescription("NDI Camera");addView(logo);brand=label("NDI\nCAMERA",12,0xff4ade80);brand.setTypeface(null,1);status=label("ГОТОВО К ЭФИРУ",10,0xffb4ffcd);timer=label("00:00:00",12,Color.WHITE);bitrate=label("— Мбит/с",10,0xffd3dfec);source=label("Android Camera",9,0xffd3dfec);zoomText=label("1×",12,0xffb4ffcd);
  button("lock","↻","Блокировка ориентации");button("settings","⚙","Настройки");button("grid","▦","Сетка");button("light","ϟ","Подсветка");button("ev","EV","Экспокоррекция");button("ae","AE-L","Зафиксировать экспозицию");button("af","AF-L","Зафиксировать фокус");button("mf","MF","Ручной фокус");button("scopes","◎","Вектроскоп и RGB-гистограмма");button("hide","HIDE","Скрыть оверлей");button("camera","⇄ Тыловая","Переключить камеру");button("swap","⇄","Поменять основную камеру и PIP");button("quality","720p · 30","Разрешение и частота кадров");button("lenses","◎ 1×","Выбрать объектив");button("start","START","Начать / остановить трансляцию");button("mute","MUTE","Выключить / включить микрофон");button("restore","HUD","Показать оверлей");
  GradientDrawable red=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{0xffa9444d,0xff421e29});red.setShape(GradientDrawable.OVAL);red.setStroke(dp(3),0xfff87171);buttons.get("start").setBackground(red);buttons.get("start").setTextSize(11);
  zoom=new SeekBar(c);zoom.setMax(1000);zoom.setRotation(-90);zoom.setProgressTintList(android.content.res.ColorStateList.valueOf(0xff4ade80));zoom.setThumbTintList(android.content.res.ColorStateList.valueOf(0xff4ade80));zoom.setContentDescription("Зум");addView(zoom);zoom.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int p,boolean from){if(from&&!programmatic)actions.zoom(camera.minZoom+p/1000f*(camera.maxZoom-camera.minZoom));}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}});
  scale=new ScaleGestureDetector(c,new ScaleGestureDetector.SimpleOnScaleGestureListener(){@Override public boolean onScaleBegin(ScaleGestureDetector d){multi=true;removeCallbacks(hold);pinchZoom=camera.zoom;return true;}@Override public boolean onScale(ScaleGestureDetector d){pinchZoom=Math.max(camera.minZoom,Math.min(camera.maxZoom,pinchZoom*d.getScaleFactor()));actions.zoom(pinchZoom);return true;}});
  hold=()->{if(!multi&&!swiping){holding=true;actions.focus(pointX,pointY,true);performHapticFeedback(HapticFeedbackConstants.LONG_PRESS);}};
  setOnApplyWindowInsetsListener((v,insets)->{if(android.os.Build.VERSION.SDK_INT>=30){Insets bars=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());setPadding(bars.left,bars.top,bars.right,bars.bottom);}else setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());requestLayout();return insets;});
 }
 int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}
 private TextView label(String value,int size,int color){TextView v=new TextView(getContext());v.setText(value);v.setTextSize(size);v.setTextColor(color);v.setGravity(Gravity.CENTER);v.setShadowLayer(3,0,1,Color.BLACK);addView(v);return v;}
 private Button button(String id,String text,String description){Button b=new Button(getContext());b.setText(text);b.setTextSize(10);b.setAllCaps(false);b.setTextColor(Color.WHITE);b.setPadding(0,0,0,0);b.setMinWidth(0);b.setMinimumWidth(0);b.setMinHeight(0);b.setMinimumHeight(0);b.setIncludeFontPadding(false);b.setGravity(Gravity.CENTER);b.setContentDescription(description);GradientDrawable shape=new GradientDrawable();shape.setColor(0xd90f172a);shape.setCornerRadius(dp(24));shape.setStroke(dp(1),0xff344059);b.setBackground(shape);b.setOnClickListener(v->actions.action(id));buttons.put(id,b);addView(b);return b;}
 private void place(View v,int x,int y,int w,int h){LayoutParams p=new LayoutParams(Math.max(1,w),Math.max(1,h));p.leftMargin=x;p.topMargin=y;v.setLayoutParams(p);}
 @Override protected void onSizeChanged(int w,int h,int oldw,int oldh){super.onSizeChanged(w,h,oldw,oldh);post(this::layoutControls);}
 private void layoutControls(){int left=getPaddingLeft(),top=getPaddingTop(),w=getWidth()-left-getPaddingRight(),h=getHeight()-top-getPaddingBottom();if(w<=0||h<=0)return;boolean land=w>h;int margin=dp(12),unit=dp(34),row=top+dp(88),tool=(w-margin*2-dp(4)*7)/8;
  place(logo,left+margin,top+dp(10),dp(32),dp(32));place(brand,left+margin+dp(36),top+dp(10),dp(55),dp(35));place(buttons.get("settings"),left+w-margin-unit,top+dp(10),unit,unit);place(buttons.get("lock"),left+w-margin-unit*2-dp(6),top+dp(10),unit,unit);
  place(status,left+margin,top+dp(52),dp(145),dp(22));place(bitrate,left+w-margin-dp(120),top+dp(52),dp(120),dp(22));String[] tools={"grid","light","ev","ae","af","mf","scopes","hide"};for(int i=0;i<tools.length;i++)place(buttons.get(tools[i]),left+margin+i*(tool+dp(4)),row,tool,unit);
  int line=row+dp(44),cameraWidth=dp(108);place(buttons.get("camera"),left+w-margin-cameraWidth,line,cameraWidth,unit);place(buttons.get("swap"),left+w-margin-cameraWidth-unit-dp(6),line,unit,unit);place(buttons.get("quality"),left+margin,line,dp(105),unit);
  int audioTop=top+h-dp(53),startX=left+w-margin-dp(62)-(land?dp(70):0),startY=audioTop-dp(132);place(buttons.get("start"),startX,startY,dp(62),dp(62));place(timer,startX-dp(8),startY+dp(68),dp(78),dp(22));place(source,startX-dp(15),startY+dp(89),dp(92),dp(20));place(buttons.get("mute"),left+w-margin-dp(53),audioTop+dp(9),dp(53),dp(30));place(buttons.get("lenses"),left+w/2-dp(46),audioTop-dp(83),dp(92),dp(32));
  int centerY;
  centerY=top+(int)(h*(land?.5f:.50f));centerY=Math.max(line+dp(95),Math.min(startY-dp(95),centerY));
  int sliderLength=land?Math.max(dp(40),Math.min(dp(100),audioTop-line-unit-dp(56))):dp(140);if(land)centerY=line+unit+dp(40)+sliderLength/2;place(zoom,left+w-margin-dp(22)-sliderLength/2,centerY-dp(22),sliderLength,dp(44));place(zoomText,left+w-margin-dp(44),centerY-sliderLength/2-dp(30),dp(44),dp(24));place(buttons.get("restore"),left+w-margin-dp(56),top+dp(10),dp(56),unit);buttons.get("restore").setVisibility(hidden?VISIBLE:GONE);
 }
 void update(boolean live,boolean muted,boolean showBitrate,boolean locked,String name,StreamSession stream){
  buttons.get("start").setText(live?"STOP":"START");buttons.get("mute").setText(muted?"UNMUTE":"MUTE");buttons.get("camera").setText(camera.pip?"⇄ Обе · PIP":camera.mainFront?"⇄ Фронт.":"⇄ Тыловая");buttons.get("swap").setVisibility(!hidden&&camera.pip?VISIBLE:GONE);buttons.get("quality").setText(camera.height+"p · "+camera.fps);buttons.get("lock").setText(locked?"▣":"↻");buttons.get("lenses").setText(String.format(Locale.US,"◎ %.1f×",camera.zoom));
  active("grid",grid);active("light",camera.torch||frontLight);active("ae",camera.aeLock);active("af",camera.afLock);active("mf",camera.manual);active("scopes",scopes);buttons.get("af").setEnabled(camera.supportsAf()&&!camera.manual);buttons.get("ae").setEnabled(camera.supportsAeLock());buttons.get("mf").setEnabled(camera.supportsManual());
  bitrate.setVisibility(!hidden&&showBitrate?VISIBLE:GONE);bitrate.setText(stream==null||stream.mbps<0?"— Мбит/с":String.format(Locale.US,"≈ %.1f Мбит/с",stream.mbps));status.setText(live?"● ЭФИР · "+(stream==null?0:stream.receivers)+" приёмн.":camera.ready?"● ГОТОВО К ЭФИРУ":"● ОТКРЫТИЕ КАМЕРЫ");
  long seconds=stream==null?0:(android.os.SystemClock.elapsedRealtime()-stream.startedAt)/1000;timer.setText(String.format(Locale.US,"%02d:%02d:%02d",seconds/3600,seconds/60%60,seconds%60));source.setText(name);level=stream==null?-90:stream.dbfs;programmatic=true;zoom.setProgress(camera.maxZoom==camera.minZoom?0:Math.round(1000*(camera.zoom-camera.minZoom)/(camera.maxZoom-camera.minZoom)));programmatic=false;zoomText.setText(String.format(Locale.US,"%.1f×",camera.zoom));invalidate();
 }
 private void active(String id,boolean on){Button b=buttons.get(id);b.setTextColor(on?0xffb4ffcd:Color.WHITE);b.setSelected(on);b.setAlpha(b.isEnabled()?1:.45f);}
 void hide(boolean value){hidden=value;for(int i=0;i<getChildCount();i++)getChildAt(i).setVisibility(value?GONE:VISIBLE);buttons.get("restore").setVisibility(value?VISIBLE:GONE);buttons.get("swap").setVisibility(!value&&camera.pip?VISIBLE:GONE);invalidate();}
 void scopes(int[] values,int[] points){rgb=values;vector=points;postInvalidate();}
 @Override protected void onDraw(Canvas c){super.onDraw(c);int w=getWidth(),h=getHeight();float left=getPaddingLeft(),right=w-getPaddingRight(),bottom=h-getPaddingBottom();
  if(frontLight){paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(dp(28));paint.setColor(Color.WHITE);c.drawRect(dp(14),dp(14),w-dp(14),h-dp(14),paint);paint.setStyle(Paint.Style.FILL);}
  if(hidden)return;
  if(grid){paint.setStrokeWidth(1);paint.setColor(0x55ffffff);for(int i=1;i<3;i++){c.drawLine(w*i/3f,0,w*i/3f,h,paint);c.drawLine(0,h*i/3f,w,h*i/3f,paint);}}
  paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(dp(1));paint.setColor(0xffffdf79);float x=pointX*w,y=pointY*h;c.drawRoundRect(x-dp(22),y-dp(22),x+dp(22),y+dp(22),dp(4),dp(4),paint);paint.setStyle(Paint.Style.FILL);paint.setTextSize(dp(10));paint.setTextAlign(Paint.Align.CENTER);c.drawText((camera.manual?"MF":camera.afLock?"AF-L":"AF")+" / "+(camera.aeLock?"AE-L":"AE"),x,y+dp(36),paint);
  float audioTop=bottom-dp(53);paint.setColor(0xee0f172a);c.drawRect(left,audioTop,right,bottom,paint);paint.setColor(0xffdce8f5);paint.setTextAlign(Paint.Align.LEFT);paint.setTextSize(dp(10));c.drawText("MIC",left+dp(12),audioTop+dp(27),paint);float meterLeft=left+dp(43),meterRight=right-dp(145),meterWidth=Math.max(dp(12),meterRight-meterLeft);int count=24;for(int i=0;i<count;i++){float threshold=-60+i*60f/count;paint.setColor(level>=threshold?(i>=21?0xfff87171:i>=17?0xfff9d67c:0xff4ade80):0xff334155);c.drawRoundRect(meterLeft+i*meterWidth/count,audioTop+dp(16),meterLeft+(i+1)*meterWidth/count-dp(2),audioTop+dp(27),dp(1),dp(1),paint);}paint.setColor(0xffdce8f5);paint.setTextSize(dp(10));c.drawText(level<=-90?"−∞ dBFS":String.format(Locale.US,"%.1f dBFS",level),right-dp(137),audioTop+dp(26),paint);paint.setTextSize(dp(8));for(int i=0;i<4;i++)c.drawText(new String[]{"−60","−36","−18","0"}[i],meterLeft+i*meterWidth/3,audioTop+dp(43),paint);
  if(scopes&&rgb!=null){float sx=left+dp(12),sy=getPaddingTop()+dp(260),sw=dp(95),sh=dp(65);if(w>h){sx=left+dp(190);sy=getPaddingTop()+dp(183);}drawScopes(c,sx,sy,sw,sh);}
 }
 private void drawScopes(Canvas c,float x,float y,float w,float h){paint.setColor(0xdf0f172a);c.drawRoundRect(x,y,x+w,y+h,dp(8),dp(8),paint);c.drawRoundRect(x+w+dp(10),y,x+2*w+dp(10),y+h,dp(8),dp(8),paint);int max=1;for(int n:rgb)max=Math.max(max,n);int[] colors={0xfff87171,0xff4ade80,0xff60a5fa};for(int channel=0;channel<3;channel++){paint.setColor(colors[channel]);paint.setStrokeWidth(dp(1));for(int i=1;i<256;i++)c.drawLine(x+(i-1)*w/256,y+h-8-rgb[channel*256+i-1]*(h-18)/max,x+i*w/256,y+h-8-rgb[channel*256+i]*(h-18)/max,paint);}float cx=x+w*1.5f+dp(10),cy=y+h/2;paint.setColor(0xff94a3b8);paint.setStyle(Paint.Style.STROKE);c.drawCircle(cx,cy,h*.38f,paint);paint.setStyle(Paint.Style.FILL);paint.setColor(0xff4ade80);if(vector!=null)for(int v=0;v<64;v++)for(int u=0;u<64;u++)if(vector[v*64+u]>0)c.drawPoint(cx+(u-32)*h/80,cy+(v-32)*h/80,paint);}
 @Override public boolean onTouchEvent(MotionEvent e){scale.onTouchEvent(e);if(e.getPointerCount()>1){multi=true;removeCallbacks(hold);return true;}switch(e.getActionMasked()){
  case MotionEvent.ACTION_DOWN:pointer=e.getPointerId(0);downX=e.getX();downY=e.getY();downEv=camera.ev;pointX=downX/getWidth();pointY=downY/getHeight();holding=false;swiping=false;multi=false;postDelayed(hold,500);return true;
  case MotionEvent.ACTION_MOVE:if(holding&&!multi){actions.exposure(Math.max(-3,Math.min(3,downEv+(downY-e.getY())/dp(70))));invalidate();}else if(Math.hypot(e.getX()-downX,e.getY()-downY)>dp(10)){swiping=true;removeCallbacks(hold);}return true;
  case MotionEvent.ACTION_UP:removeCallbacks(hold);if(!holding&&!multi&&!swiping){actions.focus(pointX,pointY,false);performClick();}holding=false;return true;
  case MotionEvent.ACTION_CANCEL:removeCallbacks(hold);holding=false;return true;
 }return true;}
 @Override public boolean performClick(){super.performClick();return true;}
 @Override protected void onDetachedFromWindow(){removeCallbacks(hold);super.onDetachedFromWindow();}
}
